Evaluating the four inequalities in \eqref{DC} at $j=1$ gives
    \begin{equation}\label{E:deg2 constraints}
        \begin{aligned}
            a_2     & \leq \min(k-c_1-b_1,\,k-b_1-a_1), \\
            b_2+a_2 & \leq k-c_1,                       \\
            c_2+b_2 & \leq k-c_1.
        \end{aligned}
    \end{equation}
    The initial conditions for $\Pi_{(k_1,c_1,k_0+k_2-c_1)}$ are
    \begin{align*}
        a_2     & \leq k_1,   \\
        b_2+a_2 & \leq k-c_1, \\
        c_2+b_2 & \leq k-c_1.
    \end{align*}
    The last two inequalities already agree with
    \eqref{E:deg2 constraints}. For the first, the defining conditions
    of $\mathcal{S}(K)$ give $b_1+a_1\leq k_0+k_2$ and
    $c_1+b_1\leq k_0+k_2$ with at least one equality, so
    $\max(b_1+a_1,\,c_1+b_1)=k_0+k_2$. Hence
    \begin{align*}
        \min(k-c_1-b_1,\,k-b_1-a_1) & = k-\max(c_1+b_1,\,b_1+a_1) \\
                                    & = k-(k_0+k_2) = k_1.
    \end{align*}

\label{T:main}
    Let $K=(k_0,k_1,k_2)$ be a level $k$ weight.

    If $k_0+k_2>0$, let $K^{-}$ and $\mathcal{S}(K)$ be as in
    Definition~\ref{D:Kminus} and Proposition~\ref{P:S(K)}. Then
    \begin{equation}\label{E:main}
        \chi_K(\mathbf{z},q)-\chi_{K^{-}}(\mathbf{z},q)
        = \sum_{i=0}^{k_0+k_2}\mathcal{P}_i(\mathbf{z},q)\,
        \chi_{(k_1,i,k_0+k_2-i)}(\mathbf{z}q,q),
    \end{equation}
    where $\mathbf{z}q=(z_1q,z_2q,z_3q)$ and
    \begin{equation}\label{E:Pm}
        \mathcal{P}_i(\mathbf{z},q) =
        \sum_{\substack{(a_1,b_1,c_1)\in\mathcal{S}(K)\\c_1=i}}
        z_1^{a_1}\,z_2^{b_1}\,z_3^{c_1}\,q^{a_1+b_1+c_1}.
    \end{equation}

    If $k_0+k_2=0$, then $K=(0,k,0)$ and
    \begin{equation}\label{E:base}
        \chi_{(0,k,0)}(\mathbf{z},q)
        =
        \chi_{(k,0,0)}(\mathbf{z}q,q).
    \end{equation}

\label{C:Pm explicit}
    For $i=0,\ldots,k_0+k_2$,
    \begin{equation}\label{E:Pm explicit}
        \mathcal{P}_i(\mathbf{z},q) = z_3^i\bigg[
        q^{k_0+k_2+i}\!\sum_{a_1=i}^{k_0} z_2^{k_0+k_2-a_1}\,z_1^{a_1}
        \,+\, z_2^{k_0+k_2-i}q^{k_0+k_2}\!\sum_{a_1=0}^{\min(i-1,k_0)}(z_1q)^{a_1}
        \bigg],
    \end{equation}
    with the convention that the first sum is empty when $i>k_0$ and the second is empty when $i=0$.

\label{T:level-one-character-formulas}
    Define
    \[
        F(\mathbf z,q)
        =
        \sum_{n_1,n_2,n_3\geq0}
        \frac{q^{n_1^2+n_3^2+\binom{n_2+1}{2}+n_1n_2+n_2n_3}}
        {(q)_{n_2}(q)_{n_1+n_3}}
        \binom{n_1+n_3}{n_1}_{q^2}\,
        z_1^{n_1}z_2^{n_2}z_3^{n_3}.
    \]
    Here $n_1,n_2,n_3$ record the multiplicities of the colors $2,0,\underline 2$,
    corresponding to the variables $z_1,z_2,z_3$, respectively. Then the level $1$
    characters are given by
    \begin{equation}\label{E:level-one-chi}
        \begin{aligned}
            \chi_{1,0,0}
             & = F(\mathbf z,q),  \\
            \chi_{0,1,0}
             & = F(\mathbf zq,q), \\
            \chi_{0,0,1}
             & =
            F\bigl((z_1q,\,z_2,\,z_3q),\,q\bigr)
            + qz_3\,F\bigl((z_1q^2,\,z_2q,\,z_3q^2),\,q\bigr).
        \end{aligned}
    \end{equation}

By Theorem~\ref{T:uniqueness}, it is enough to show that the three series in
    \eqref{E:level-one-chi} satisfy \eqref{E:lvl1 r1}--\eqref{E:lvl1 r3} and have
    constant term $1$. The first two series have constant term $1$. For the third
    series, the first summand has constant term $1$, while the second summand is
    divisible by $q$. Relation \eqref{E:lvl1 r3} follows directly from
    \eqref{E:level-one-chi}.

    Let $f_{n_1,n_2,n_3}$ denote the coefficient of $z_1^{n_1}z_2^{n_2}z_3^{n_3}$
    in $F(\mathbf z,q)$ for $n_1,n_2,n_3\geq0$. We set $f_{n_1,n_2,n_3}=0$ whenever
    $n_1<0$, $n_2<0$, or $n_3<0$. Thus
    \[
        f_{n_1,n_2,n_3}
        =
        \frac{q^{n_1^2+n_3^2+\binom{n_2+1}{2}+n_1n_2+n_2n_3}}
        {(q)_{n_2}\,(q)_{n_1+n_3}}
        \binom{n_1+n_3}{n_1}_{q^2}.
    \]
    Comparing the powers of $q$ and the factors $(q)_{n_2}$ gives, for $0\leq m\leq
        n_2$,
    \begin{equation}\label{E:f-ratio}
        f_{n_1,n_2-m,n_3}
        =
        q^{\binom{m}{2}-m(n_1+n_2+n_3)}
        \frac{(q)_{n_2}}{(q)_{n_2-m}}\,
        f_{n_1,n_2,n_3}.
    \end{equation}

    \emph{Relation \eqref{E:lvl1 r2}.} First we prove
    \begin{equation}\label{E:level-one-chi-sum}
        \chi_{0,0,1}
        =
        \sum_{m\geq0}
        q^{\binom{m+1}{2}}z_2^m
        \left(
        F(\mathbf zq^{m+1},q)
        +q^{m+1}z_3\,F(\mathbf zq^{m+2},q)
        \right).
    \end{equation}
    The contribution of the terms containing $F(\mathbf zq^{m+1},q)$ to
    the coefficient of $z_1^{n_1}z_2^{n_2}z_3^{n_3}$ on the right side of
    \eqref{E:level-one-chi-sum} equals
    \begin{align*}
         &
        \sum_{m=0}^{n_2}
        q^{\binom{m+1}{2}+(m+1)(n_1+n_2-m+n_3)}
        f_{n_1,n_2-m,n_3}
        \\
         & =
        \sum_{m=0}^{n_2}
        q^{n_1+n_2+n_3-m}
        \frac{(q)_{n_2}}{(q)_{n_2-m}}\,
        f_{n_1,n_2,n_3}
        \\
         & =
        q^{n_1+n_3}\,(q)_{n_2}\,f_{n_1,n_2,n_3}
        \sum_{m=0}^{n_2}
        \frac{q^{n_2-m}}{(q)_{n_2-m}}
        \\
         & =
        q^{n_1+n_3}\,f_{n_1,n_2,n_3}.
    \end{align*}
    The second equality follows from \eqref{E:f-ratio}, and the last one
    from Euler's identity
    \[
        \sum_{m=0}^{n}\frac{q^m}{(q)_m}
        =
        \frac{1}{(q)_n}.
    \]
    This equals the coefficient of $z_1^{n_1}z_2^{n_2}z_3^{n_3}$ in
    \[
        F\bigl((z_1q,\,z_2,\,z_3q),\,q\bigr).
    \]

    For $n_3>0$, the contribution of the terms containing $q^{m+1}z_3F(\mathbf
        zq^{m+2},q)$ to the coefficient of $z_1^{n_1}z_2^{n_2}z_3^{n_3}$ on the right
    side of \eqref{E:level-one-chi-sum} equals
    \begin{align*}
         &
        \sum_{m=0}^{n_2}
        q^{
                \binom{m+1}{2}
                +m+1
                +(m+2)(n_1+n_2-m+n_3-1)
            }
        f_{n_1,n_2-m,n_3-1}
        \\
         & =
        \sum_{m=0}^{n_2}
        q^{2n_1+2n_2+2n_3-1-m}
        \frac{(q)_{n_2}}{(q)_{n_2-m}}\,
        f_{n_1,n_2,n_3-1}
        \\
         & =
        q^{2n_1+n_2+2n_3-1}
        (q)_{n_2}\,f_{n_1,n_2,n_3-1}
        \sum_{m=0}^{n_2}
        \frac{q^{n_2-m}}{(q)_{n_2-m}}
        \\
         & =
        q^{2n_1+n_2+2n_3-1}
        f_{n_1,n_2,n_3-1}.
    \end{align*}
    For $n_3=0$ the contribution is zero. Therefore the two contributions
    give the coefficients of the two summands in
    \[
        F\bigl((z_1q,\,z_2,\,z_3q),\,q\bigr)
        +
        qz_3\,F\bigl((z_1q^2,\,z_2q,\,z_3q^2),\,q\bigr),
    \]
    and \eqref{E:level-one-chi-sum} follows from \eqref{E:level-one-chi}.

    Substituting $\mathbf z\mapsto\mathbf zq$ in \eqref{E:level-one-chi-sum} and
    multiplying by $qz_2$ gives
    \begin{align*}
        qz_2\,\chi^+_{0,0,1}
         & =
        \sum_{m\geq0}
        q^{\binom{m+1}{2}+m+1}
        z_2^{m+1}
        \left(
        F(\mathbf zq^{m+2},q)
        +q^{m+2}z_3\,F(\mathbf zq^{m+3},q)
        \right)
        \\
         & =
        \sum_{m\geq1}
        q^{\binom{m+1}{2}}
        z_2^m
        \left(
        F(\mathbf zq^{m+1},q)
        +q^{m+1}z_3\,F(\mathbf zq^{m+2},q)
        \right).
    \end{align*}
    This is the part of \eqref{E:level-one-chi-sum} with $m\geq1$. The
    summand with $m=0$ is
    \[
        F(\mathbf zq,q)+qz_3\,F(\mathbf zq^2,q)
        =
        \chi_{0,1,0}+qz_3\,\chi^+_{0,1,0}.
    \]
    Together these two parts give
    \[
        \chi_{0,0,1}
        =
        \chi_{0,1,0}
        +qz_3\,\chi^+_{0,1,0}
        +qz_2\,\chi^+_{0,0,1},
    \]
    which is \eqref{E:lvl1 r2}.

    \emph{Relation \eqref{E:lvl1 r1}.} The coefficient of
    $z_1^{n_1}z_2^{n_2}z_3^{n_3}$ in $\chi_{1,0,0}-\chi_{0,1,0}$ is
    \[
        (1-q^{n_1+n_2+n_3})\,f_{n_1,n_2,n_3}.
    \]
    The right side of \eqref{E:lvl1 r1} is
    \[
        qz_2\,\chi^+_{0,0,1}
        +qz_1\,\chi^+_{0,0,1}
        +qz_3\,\chi^+_{0,1,0}
        +q^2z_1z_3\,\chi^+_{0,1,0}.
    \]
    Using \eqref{E:level-one-chi}, the coefficients of
    $z_1^{n_1}z_2^{n_2}z_3^{n_3}$ in these four terms are
    \begin{align}
        qz_2\,\chi^+_{0,0,1}
         & :\
        q^{2n_1+n_2+2n_3}\,f_{n_1,n_2-1,n_3}
        \notag
        \\
         & \quad
        +q^{3n_1+2n_2+3n_3-2}\,
        f_{n_1,n_2-1,n_3-1},
        \label{E:lvl1 coeff z2}
        \\[2pt]
        qz_1\,\chi^+_{0,0,1}
         & :\
        q^{2n_1+n_2+2n_3-1}\,f_{n_1-1,n_2,n_3}
        \notag
        \\
         & \quad
        +q^{3n_1+2n_2+3n_3-3}\,
        f_{n_1-1,n_2,n_3-1},
        \label{E:lvl1 coeff z1}
        \\[2pt]
        qz_3\,\chi^+_{0,1,0}
         & :\
        q^{2n_1+2n_2+2n_3-1}\,
        f_{n_1,n_2,n_3-1},
        \label{E:lvl1 coeff z3}
        \\[2pt]
        q^2z_1z_3\,\chi^+_{0,1,0}
         & :\
        q^{2n_1+2n_2+2n_3-2}\,
        f_{n_1-1,n_2,n_3-1}.
        \label{E:lvl1 coeff z1z3}
    \end{align}

    The definition of the Gaussian binomial coefficients gives the following
    identities. For $n_1>0$,
    \begin{equation}\label{E:gb1}
        \frac{(q)_{n_1+n_3}}{(q)_{n_1+n_3-1}}\,
        \frac{\binom{n_1+n_3-1}{n_1-1}_{q^2}}
        {\binom{n_1+n_3}{n_1}_{q^2}}
        =
        \frac{1-q^{2n_1}}{1+q^{n_1+n_3}}.
    \end{equation}
    For $n_3>0$,
    \begin{equation}\label{E:gb2}
        \frac{(q)_{n_1+n_3}}{(q)_{n_1+n_3-1}}\,
        \frac{\binom{n_1+n_3-1}{n_1}_{q^2}}
        {\binom{n_1+n_3}{n_1}_{q^2}}
        =
        \frac{1-q^{2n_3}}{1+q^{n_1+n_3}}.
    \end{equation}
    For $n_1,n_3>0$,
    \begin{equation}\label{E:gb3}
        (1+q^{n_1+n_3-1})\,
        \frac{(q)_{n_1+n_3}}{(q)_{n_1+n_3-2}}\,
        \frac{\binom{n_1+n_3-2}{n_1-1}_{q^2}}
        {\binom{n_1+n_3}{n_1}_{q^2}}
        =
        \frac{(1-q^{2n_1})(1-q^{2n_3})}
        {1+q^{n_1+n_3}}.
    \end{equation}

    Dividing the sum of \eqref{E:lvl1 coeff z2}--\eqref{E:lvl1 coeff z1z3} by
    $f_{n_1,n_2,n_3}$ and using \eqref{E:f-ratio}, \eqref{E:gb1}, \eqref{E:gb2} and
    \eqref{E:gb3} gives
    \begin{align*}
         &
        q^{n_1+n_3}(1-q^{n_2})
        \\
         & \quad
        +\frac{
        q^{2n_3}(1-q^{2n_1})
        +q^{2n_1}(1-q^{n_2})(1-q^{2n_3})
        }{
        1+q^{n_1+n_3}
        }
        \\
         & \quad
        +\frac{
        q^{2n_1+n_2}(1-q^{2n_3})
        +(1-q^{2n_1})(1-q^{2n_3})
        }{
        1+q^{n_1+n_3}
        }.
    \end{align*}
    The numerator of the two fractions equals
    \begin{align*}
         &
        q^{2n_3}(1-q^{2n_1})
        +q^{2n_1}(1-q^{n_2})(1-q^{2n_3})
        \\
         & \quad
        +q^{2n_1+n_2}(1-q^{2n_3})
        +(1-q^{2n_1})(1-q^{2n_3})
        \\
         & =
        q^{2n_3}(1-q^{2n_1})
        +q^{2n_1}(1-q^{2n_3})
        +(1-q^{2n_1})(1-q^{2n_3})
        \\
         & =
        1-q^{2n_1+2n_3}.
    \end{align*}
    The total contribution divided by $f_{n_1,n_2,n_3}$ is therefore
    \begin{align*}
         &
        q^{n_1+n_3}(1-q^{n_2})
        +
        \frac{1-q^{2n_1+2n_3}}{1+q^{n_1+n_3}}
        \\
         & =
        q^{n_1+n_3}(1-q^{n_2})
        +1-q^{n_1+n_3}
        \\
         & =
        1-q^{n_1+n_2+n_3}.
    \end{align*}
    Multiplying by $f_{n_1,n_2,n_3}$ gives the coefficient of
    $z_1^{n_1}z_2^{n_2}z_3^{n_3}$ in
    $\chi_{1,0,0}-\chi_{0,1,0}$. This proves \eqref{E:lvl1 r1}.

\label{C:character identity}
    The character $\widetilde{\chi}_{(\bar{k}_0,\bar{k}_1)}$ satisfies
    \begin{equation}\label{E:character identity}
        \widetilde{\chi}_{(\bar{k}_0,\bar{k}_1)}(\mathbf{z},q)
        = \sum_{m=0}^{\bar{k}_1} z_3^{m}\,\chi_{(\bar{k}_0,\,m,\,\bar{k}_1-m)}(\mathbf{z},q).
    \end{equation}
